{
  "name": "event-horizon-vscode",
  "publisher": "HeytalePazguato",
  "version": "3.3.0",
  "private": true,
  "displayName": "Event Horizon",
  "description": "Multi-agent orchestration for AI coding agents. One agent creates the plan, spawns the team, and manages the project. Shared plans, file locking, inter-agent messaging, budget controls, and live visualization. Works with Claude Code, OpenCode, Copilot, and Cursor.",
  "license": "MIT",
  "main": "out/extension.js",
  "icon": "assets/icon.png",
  "galleryBanner": {
    "color": "#0a0f18",
    "theme": "dark"
  },
  "engines": {
    "vscode": "^1.100.0"
  },
  "categories": [
    "Visualization",
    "Other"
  ],
  "keywords": [
    "ai",
    "agents",
    "multi-agent",
    "agent-orchestration",
    "orchestration",
    "claude-code",
    "opencode",
    "copilot",
    "cursor",
    "vscodium",
    "windsurf",
    "gitpod",
    "theia",
    "coder",
    "mcp",
    "mcp-tools",
    "ai-coordination",
    "ai-coding",
    "visualization",
    "monitoring",
    "file-locking",
    "task-management",
    "token-tracking",
    "cost-tracking",
    "software-architecture",
    "software-planning",
    "agent-spawning",
    "knowledge-sharing",
    "budget"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/HeytalePazguato/event-horizon.git"
  },
  "contributes": {
    "commands": [
      {
        "command": "eventHorizon.open",
        "title": "Event Horizon: Open Universe",
        "icon": "$(rocket)"
      },
      {
        "command": "eventHorizon.setupClaudeCode",
        "title": "Event Horizon: Connect Claude Code"
      },
      {
        "command": "eventHorizon.toggleView",
        "title": "Event Horizon: Toggle Operations View",
        "icon": "$(layout)"
      },
      {
        "command": "eventHorizon.focusWaitingAgent",
        "title": "Event Horizon: Focus Waiting Agent"
      },
      {
        "command": "eventHorizon.purgeStaleAgents",
        "title": "Event Horizon: Clear Stale Agents"
      },
      {
        "command": "eventHorizon.purgeTelemetry",
        "title": "Event Horizon: Delete Stored Claude Code Telemetry"
      },
      {
        "command": "eventHorizon.exportData",
        "title": "Event Horizon: Export Data...",
        "icon": "$(export)"
      }
    ],
    "menus": {
      "editor/title": [
        {
          "command": "eventHorizon.open",
          "group": "navigation"
        },
        {
          "command": "eventHorizon.toggleView",
          "group": "navigation",
          "when": "activeWebviewPanelId == 'eventHorizon.universe'"
        }
      ]
    },
    "keybindings": [
      {
        "command": "eventHorizon.open",
        "key": "ctrl+shift+e h",
        "mac": "cmd+shift+e h"
      },
      {
        "command": "eventHorizon.toggleView",
        "key": "ctrl+shift+e o",
        "mac": "cmd+shift+e o"
      }
    ],
    "configuration": {
      "title": "Event Horizon",
      "properties": {
        "eventHorizon.port": {
          "type": "number",
          "default": 28765,
          "minimum": 1024,
          "maximum": 65535,
          "description": "Port for the local event server that receives agent hooks. Requires extension restart.",
          "order": 1
        },
        "eventHorizon.fileLockingEnabled": {
          "type": "boolean",
          "default": false,
          "description": "Enable file locking to prevent multiple agents from writing to the same file simultaneously. When enabled, agents must acquire a lock before writing — conflicting writes are blocked. Requires reinstalling hooks.",
          "order": 2
        },
        "eventHorizon.knowledge.interceptReads": {
          "type": "boolean",
          "default": true,
          "markdownDescription": "When a Claude Code agent reads a file that is in shared knowledge and has not changed since, answer the first read with the stored summary instead of the full file. Running Read again on the same path returns the full contents, so files stay editable. Secret files are never intercepted."
        },
        "eventHorizon.worktreeIsolation": {
          "type": "boolean",
          "default": false,
          "description": "Enable git worktree isolation for spawned agents. Each agent gets its own copy of the repository — eliminates file conflicts entirely. Works with any git host (GitHub, GitLab, Bitbucket). Disable if you don't want extra branches.",
          "order": 2
        },
        "eventHorizon.animationSpeed": {
          "type": "number",
          "default": 1,
          "minimum": 0.25,
          "maximum": 3,
          "description": "Animation speed multiplier (0.25 = slow-mo, 3.0 = fast-forward).",
          "order": 2
        },
        "eventHorizon.fontSize": {
          "type": "string",
          "default": "default",
          "enum": [
            "small",
            "default",
            "large"
          ],
          "enumDescriptions": [
            "Smaller text (87%)",
            "Default text size",
            "Larger text for improved readability (115%)"
          ],
          "description": "UI font size for the Event Horizon panel. Affects all text in the universe and operations views.",
          "order": 3
        },
        "eventHorizon.defaultView": {
          "type": "string",
          "default": "universe",
          "enum": [
            "universe",
            "operations"
          ],
          "enumDescriptions": [
            "Cosmic planet visualization",
            "Full-screen dashboard with tabs"
          ],
          "description": "Which view to show when opening Event Horizon.",
          "order": 3
        },
        "eventHorizon.planShowAllColumns": {
          "type": "boolean",
          "default": false,
          "description": "Show all Kanban columns in the Plan tab, including empty ones.",
          "order": 4
        },
        "eventHorizon.achievementsEnabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable achievement medals and toast notifications.",
          "order": 5
        },
        "eventHorizon.agentColors.claudeCode": {
          "type": "string",
          "default": "#88aaff",
          "format": "color",
          "description": "Planet color for Claude Code agents.",
          "order": 10
        },
        "eventHorizon.agentColors.copilot": {
          "type": "string",
          "default": "#cc88ff",
          "format": "color",
          "description": "Planet color for GitHub Copilot agents.",
          "order": 11
        },
        "eventHorizon.agentColors.opencode": {
          "type": "string",
          "default": "#88ffaa",
          "format": "color",
          "description": "Planet color for OpenCode agents.",
          "order": 12
        },
        "eventHorizon.agentColors.cursor": {
          "type": "string",
          "default": "#44ddcc",
          "format": "color",
          "description": "Planet color for Cursor agents.",
          "order": 13
        },
        "eventHorizon.agentColors.unknown": {
          "type": "string",
          "default": "#aaccff",
          "format": "color",
          "description": "Planet color for unrecognized agent types.",
          "order": 14
        },
        "eventHorizon.agentSizes.claudeCode": {
          "type": "number",
          "default": 1.35,
          "minimum": 0.4,
          "maximum": 2,
          "description": "Planet size multiplier for Claude Code agents.",
          "order": 20
        },
        "eventHorizon.agentSizes.copilot": {
          "type": "number",
          "default": 0.72,
          "minimum": 0.4,
          "maximum": 2,
          "description": "Planet size multiplier for GitHub Copilot agents.",
          "order": 21
        },
        "eventHorizon.agentSizes.opencode": {
          "type": "number",
          "default": 1,
          "minimum": 0.4,
          "maximum": 2,
          "description": "Planet size multiplier for OpenCode agents.",
          "order": 22
        },
        "eventHorizon.agentSizes.cursor": {
          "type": "number",
          "default": 0.92,
          "minimum": 0.4,
          "maximum": 2,
          "description": "Planet size multiplier for Cursor agents.",
          "order": 23
        },
        "eventHorizon.agentSizes.unknown": {
          "type": "number",
          "default": 1.12,
          "minimum": 0.4,
          "maximum": 2,
          "description": "Planet size multiplier for unrecognized agent types.",
          "order": 24
        },
        "eventHorizon.spawnTerminalFocus": {
          "type": "string",
          "default": "focus-on-interaction",
          "enum": [
            "background",
            "focus",
            "focus-on-interaction"
          ],
          "enumDescriptions": [
            "Keep terminal in background after spawning",
            "Focus the terminal immediately after spawning",
            "Focus the terminal when the agent needs interaction (waiting state)"
          ],
          "description": "When spawning an agent via the orchestrator, how to handle terminal focus.",
          "order": 6
        },
        "eventHorizon.roles.custom": {
          "type": "array",
          "default": [],
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string",
                "description": "Unique role identifier (lowercase, hyphens allowed)"
              },
              "name": {
                "type": "string",
                "description": "Display name"
              },
              "description": {
                "type": "string",
                "description": "What this role specializes in"
              },
              "skills": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Skill names to recommend for this role"
              },
              "instructions": {
                "type": "string",
                "description": "Markdown instructions sent to the agent when assigned this role"
              }
            },
            "required": [
              "id",
              "name",
              "description"
            ]
          },
          "markdownDescription": "Define custom agent roles beyond the 6 built-in ones (researcher, planner, implementer, reviewer, tester, debugger). Each role maps to skills and instructions.",
          "order": 20
        },
        "eventHorizon.roles.assignments": {
          "type": "object",
          "default": {},
          "additionalProperties": {
            "type": "string"
          },
          "markdownDescription": "Map role IDs to default agent types. Example: `{ \"researcher\": \"claude-code\", \"reviewer\": \"copilot\" }`",
          "order": 21
        },
        "eventHorizon.contextOptimizer.threshold": {
          "type": "number",
          "default": 3000,
          "minimum": 500,
          "maximum": 20000,
          "description": "Token threshold for context optimization suggestions. A notification appears when instruction files (CLAUDE.md, .cursorrules, etc.) exceed this estimated token count.",
          "order": 8
        },
        "eventHorizon.knowledge.autoDiscover": {
          "type": "boolean",
          "default": true,
          "description": "Scan workspace instruction files (CLAUDE.md, AGENTS.md, .cursorrules, copilot-instructions.md, .claude/rules/*.md) on activation and on file changes, then surface them in the Knowledge tab tagged as source=auto. Auto entries are assigned a tier (L1 for root instructions, L2 for rules) and never overwrite user- or agent-authored entries. Disable if you only want knowledge written explicitly by agents or via the UI.",
          "order": 9
        },
        "eventHorizon.budgetWarningThreshold": {
          "type": "number",
          "default": 0.8,
          "minimum": 0.1,
          "maximum": 1,
          "description": "Budget warning threshold (0.1 to 1.0). A warning is shown when spending reaches this percentage of the plan budget.",
          "order": 7
        },
        "eventHorizon.telemetry.retentionDays": {
          "type": "number",
          "default": 7,
          "minimum": 1,
          "markdownDescription": "Days of Claude Code telemetry rollups and log records to keep in `telemetry.sqlite`. Older data is removed at startup. Use **Event Horizon: Delete Stored Claude Code Telemetry** to remove it all."
        },
        "eventHorizon.claudeStatusLine.mode": {
          "type": "string",
          "enum": ["chain", "always", "off"],
          "enumDescriptions": [
            "Wrap your existing Claude Code statusLine so Event Horizon also receives its data. Installs nothing if you have no statusLine.",
            "Also install one when you have none, showing a compact [model] ctx % · $cost line. A custom statusLine hides Claude Code's footer keyboard hints.",
            "Remove the bridge and restore your original statusLine."
          ],
          "default": "chain",
          "markdownDescription": "How Event Horizon reads Claude Code's statusLine data (its own session cost, prompt-cache hit ratio, cache-miss causes and context usage). Your original statusLine is saved and runs unchanged; it is restored when this is `off` or hooks are removed."
        },
        "eventHorizon.claudeTelemetry.enabled": {
          "type": "boolean",
          "default": true,
          "markdownDescription": "Send Claude Code's OpenTelemetry cost and usage data to Event Horizon so agent cost is measured rather than estimated. Writes per-signal `OTEL_*` variables into the `env` block of `~/.claude/settings.json` (prompts, responses and tool contents stay off) and restores the previous values when turned off. Takes effect for Claude Code sessions started afterwards."
        },
        "eventHorizon.persistence.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable SQLite persistence for events and knowledge. Disable to run in ephemeral mode (events lost on reload).",
          "order": 30
        },
        "eventHorizon.persistence.retentionDays": {
          "type": "number",
          "default": 30,
          "minimum": 1,
          "maximum": 365,
          "description": "Number of days to retain persisted events before auto-pruning on startup.",
          "order": 31
        },
        "eventHorizon.websocket.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable WebSocket endpoint at /ws for bidirectional agent communication. External tools can connect to ws://127.0.0.1:<port>/ws and receive debounced event broadcasts.",
          "order": 32
        },
        "eventHorizon.contextGauge.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Show context usage gauge (270° arc) on planet visuals. Color shifts cyan → amber → red as agents approach their context window limit.",
          "order": 33
        },
        "eventHorizon.contextGauge.windowSize": {
          "type": "number",
          "default": 200000,
          "minimum": 1000,
          "maximum": 2000000,
          "description": "Estimated context window size in tokens (drives the planet fuel-gauge calculation). Default is 200000 for Claude Sonnet/Opus.",
          "order": 34
        },
        "eventHorizon.autoDetect.enabled": {
          "type": "boolean",
          "default": true,
          "description": "On extension activation, scan PATH for installed AI agent CLIs (claude, opencode, cursor) and offer one-click hook setup if any are found without configured hooks.",
          "order": 35
        },
        "eventHorizon.watchdog.timeoutMinutes": {
          "type": "number",
          "default": 10,
          "minimum": 0,
          "maximum": 120,
          "description": "Auto-fail spawned workers that have not emitted any event for this many minutes (likely stuck on a permission prompt or hung). Orchestrators are notified via the message queue. Set to 0 to disable. Interactive-mode workers are always excluded.",
          "order": 36
        },
        "eventHorizon.projectGraph.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable workspace project graph (code structure + docs + agent activity). The graph is built only on user invocation; nothing runs in the background.",
          "order": 40
        },
        "eventHorizon.projectGraph.maxFiles": {
          "type": "number",
          "default": 5000,
          "minimum": 100,
          "maximum": 100000,
          "description": "Cap on file count for a workspace scan. Workspaces over this size require manual confirmation.",
          "order": 41
        },
        "eventHorizon.projectGraph.includeMarkdown": {
          "type": "boolean",
          "default": true,
          "description": "Extract concepts from markdown files.",
          "order": 42
        },
        "eventHorizon.projectGraph.allowAgentLLMExtraction": {
          "type": "boolean",
          "default": true,
          "description": "Allow agents to add INFERRED nodes via the eh_extract_concepts MCP tool. EH itself never makes outbound model calls.",
          "order": 43
        },
        "eventHorizon.projectGraph.maxFileSizeKb": {
          "type": "number",
          "default": 256,
          "minimum": 16,
          "maximum": 8192,
          "description": "Skip files larger than this size (KB) during workspace scans. Defaults to 256 KB — comfortably fits hand-written source while excluding inline-bundled vendor scripts that explode the graph with useless nodes.",
          "order": 44
        },
        "eventHorizon.projectGraph.canvasMaxNodes": {
          "type": "number",
          "default": 5000,
          "minimum": 200,
          "maximum": 50000,
          "description": "Maximum number of nodes to render in the Project Graph canvas at once. The canvas uses Barnes-Hut layout with viewport culling, so even thousands of nodes stay responsive — but enormous monorepos (50k+ nodes) can still saturate the SVG renderer. Lower this if pan/zoom feels sluggish; raise it if you need to see the full graph.",
          "order": 45
        }
      }
    },
    "walkthroughs": [
      {
        "id": "eventHorizon.gettingStarted",
        "title": "Get Started with Event Horizon",
        "description": "Set up your AI coding agent universe in 5 steps.",
        "steps": [
          {
            "id": "openUniverse",
            "title": "Open the Universe",
            "description": "Open the Event Horizon panel from the activity bar.\n\n[Open Universe](command:eventHorizon.open)",
            "media": {
              "markdown": "assets/walkthrough/open-universe.md"
            },
            "completionEvents": [
              "onView:eventHorizon.universe"
            ]
          },
          {
            "id": "connectAgent",
            "title": "Connect an Agent",
            "description": "Install hooks for Claude Code, OpenCode, or GitHub Copilot.\n\n[Connect Claude Code](command:eventHorizon.setupClaudeCode)",
            "media": {
              "markdown": "assets/walkthrough/connect-agent.md"
            },
            "completionEvents": [
              "onCommand:eventHorizon.setupClaudeCode"
            ]
          },
          {
            "id": "exploreUniverse",
            "title": "Explore the Universe",
            "description": "Planets, ships, lightning arcs, astronauts — discover the cosmic visualization.",
            "media": {
              "markdown": "assets/walkthrough/explore-universe.md"
            }
          },
          {
            "id": "commandCenter",
            "title": "Use the Command Center",
            "description": "Select planets, view metrics, control agents, and earn achievements.",
            "media": {
              "markdown": "assets/walkthrough/command-center.md"
            }
          },
          {
            "id": "skills",
            "title": "Manage Agent Skills",
            "description": "Discover, create, organize, and browse skills from the marketplace.",
            "media": {
              "markdown": "assets/walkthrough/skills.md"
            }
          }
        ]
      }
    ]
  },
  "scripts": {
    "build": "node scripts/build-plugins.mjs && node scripts/build-extension.mjs && node scripts/copy-sql-wasm.mjs && node scripts/copy-tree-sitter-wasm.mjs && pnpm run build:webview",
    "lint": "eslint src/ webview/",
    "build:ext": "node scripts/build-plugins.mjs && node scripts/build-extension.mjs && node scripts/copy-sql-wasm.mjs && node scripts/copy-tree-sitter-wasm.mjs",
    "build:ext:prod": "node scripts/build-plugins.mjs && node scripts/build-extension.mjs --prod && node scripts/copy-sql-wasm.mjs && node scripts/copy-tree-sitter-wasm.mjs",
    "build:webview": "node webview/esbuild.mjs",
    "build:webview:dev": "node webview/esbuild.mjs --dev",
    "build:webview:prod": "node webview/esbuild.mjs --minify",
    "package:vsix": "pnpm run build:ext:prod && pnpm run build:webview:prod && vsce package --no-dependencies",
    "test": "vitest run",
    "dev": "tsc --watch",
    "clean": "rm -rf out webview-dist"
  },
  "dependencies": {
    "@event-horizon/connectors": "workspace:*",
    "@event-horizon/core": "workspace:*",
    "@event-horizon/renderer": "workspace:*",
    "@event-horizon/ui": "workspace:*",
    "html2canvas": "^1.4.1",
    "sql.js": "^1.14.2",
    "tree-sitter-c-sharp": "^0.23.0",
    "tree-sitter-javascript": "^0.25.0",
    "tree-sitter-php": "^0.24.2",
    "tree-sitter-python": "^0.25.0",
    "tree-sitter-typescript": "^0.23.0",
    "web-tree-sitter": "^0.27.0",
    "ws": "^8.22.0"
  },
  "devDependencies": {
    "@types/node": "^26.2.0",
    "@types/react": "^19.3.0",
    "@types/react-dom": "^19.3.0",
    "@types/sql.js": "^1.4.11",
    "@types/vscode": "^1.100.0",
    "@types/ws": "^8.18.2",
    "@vscode/vsce": "^3.9.2",
    "esbuild": "^0.28.2",
    "ovsx": "^1.1.1",
    "react": "^19.3.0",
    "react-dom": "^19.3.0",
    "typescript": "^5.9.3"
  }
}
